SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;


-- ---------- 数据库：canteen_waste_monitor ----------
CREATE DATABASE IF NOT EXISTS `canteen_waste_monitor` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `canteen_waste_monitor`;

DROP TABLE IF EXISTS `detection_records`;
CREATE TABLE `detection_records` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `record_type` enum('single','batch','camera') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检测类型：单张/批量/摄像头',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检测文件名称',
  `file_size` int DEFAULT NULL COMMENT '文件大小（字节）',
  `original_image_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原图URL/路径',
  `result_image_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检测结果图URL/路径',
  `mask_image_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '掩码图URL/路径',
  `wastage_rate` decimal(5,2) DEFAULT NULL COMMENT '浪费率（%）',
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'success' COMMENT '检测状态：success/failed',
  `error_msg` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息（检测失败时）',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `waste_cause` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '弃因分析结果',
  `waste_cause_confidence` decimal(5,4) DEFAULT NULL COMMENT '弃因置信度',
  PRIMARY KEY (`id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_record_type` (`record_type`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=11105 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='餐食浪费检测记录主表';

