DROP TABLE IF EXISTS `detection_items`;
CREATE TABLE `detection_items` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `record_id` bigint NOT NULL COMMENT '关联检测记录ID',
  `food_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜品名称',
  `confidence` decimal(5,2) DEFAULT NULL COMMENT '识别置信度（%）',
  `bbox_x1` int DEFAULT NULL COMMENT '检测框左上角X坐标',
  `bbox_y1` int DEFAULT NULL COMMENT '检测框左上角Y坐标',
  `bbox_x2` int DEFAULT NULL COMMENT '检测框右下角X坐标',
  `bbox_y2` int DEFAULT NULL COMMENT '检测框右下角Y坐标',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_record_id` (`record_id`),
  KEY `idx_food_name` (`food_name`),
