DROP TABLE IF EXISTS `system_config`;
CREATE TABLE `system_config` (
  `id` int NOT NULL AUTO_INCREMENT,
  `config_key` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置键',
  `config_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置值',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '配置名称',
  PRIMARY KEY (`id`),
  UNIQUE KEY `config_key` (`config_key`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `system_config` (`id`, `config_key`, `config_value`, `name`) VALUES (1,'image_clean_days','7','图片自动清理天数'),(2,'records_clean_days','90','检测记录自动清理天数'),(5,'daily_summary_hour','2','Daily Summary Hour'),(6,'daily_summary_minute','0','Daily Summary Minute'),(7,'summary_keep_days','90','Summary Keep Days');

DROP TABLE IF EXISTS `judge_evaluations`;
CREATE TABLE `judge_evaluations` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `record_id` bigint NOT NULL COMMENT '关联检测记录ID',
  `result` enum('correct','incorrect') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评委判定：正确/错误',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '评价时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_record_id` (`record_id`),
  CONSTRAINT `fk_judge_record` FOREIGN KEY (`record_id`) REFERENCES `detection_records` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=368 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='评委打分记录表';

